class CartRemoveButton extends HTMLElement {
    constructor() {
        super();
        this.addEventListener("click", (a) => {
            a.preventDefault();
            (this.closest("cart-items") || this.closest("cart-drawer-items")).updateQuantity(this.dataset.index, 0);
        });
    }
}
customElements.define("cart-remove-button", CartRemoveButton);
class CartItems extends HTMLElement {
    constructor() {
        super();
        this.lineItemStatusElement = document.getElementById("shopping-cart-line-item-status") || document.getElementById("CartDrawer-LineItemStatus");
        this.currentItemCount = Array.from(this.querySelectorAll('[name="updates[]"]:not([type="hidden"]')).reduce((a, b) => a + parseInt(b.value), 0);
        this.debouncedOnChange = debounce((a) => {
            this.onChange(a);
        }, 300);
        this.addEventListener("change", this.debouncedOnChange.bind(this));
    }
    onChange(a) {
        this.updateQuantity(a.target.dataset.index, a.target.value, document.activeElement.getAttribute("name"));
    }
    getSectionsToRender() {
        return [
            { id: "cart-icon-bubble", section: "cart-icon-bubble", selector: ".shopify-section" },
            { id: "cart-live-region-text", section: "cart-live-region-text", selector: ".shopify-section" },
            { id: "main-cart-footer", section: document.getElementById("main-cart-footer").dataset.id, selector: ".js-contents" },
            { id: "main-cart-items", section: document.getElementById("main-cart-items").dataset.id, selector: ".js-contents" },
            { id: "CartDrawer", section: "cart-drawer", selector: ".drawer__inner" },
        ];
    }
    forceUpdateCartDrawer() {
        fetch(`${routes.cart_url}?sections=${this.getSectionsToRender().map((a) => a.section)}`)
            .then((a) => a.text())
            .then((a) => {
                const b = JSON.parse(a);
                this.getSectionsToRender().forEach((c) => {
                    "cart-drawer" === c.section && document.querySelector("cart-drawer").updateWearWith(b["cart-drawer"]);
                    const d = document.getElementById(c.id).querySelector(c.selector) || document.getElementById(c.id);
                    if (!d) return !0;
                    d.innerHTML = this.getSectionInnerHTML(b[c.section], c.selector);
                });
            });
    }
    updateQuantity(a, b, c) {
        this.enableLoading(a);
        a = JSON.stringify({
            line: a,
            quantity: b,
            sections: this.getSectionsToRender()
                .map((d) => d.section)
                .join(","),
            sections_url: window.location.pathname,
        });
        console.log(a);
        fetch(`${routes.cart_change_url}`, { ...fetchConfig(), body: a })
            .then((d) => d.text())
            .then((d) => {
                updateCart();
            })
            .catch((d) => {
                console.log(d);
                this.querySelectorAll(".loading-overlay").forEach((e) => e.classList.add("hidden"));
                (document.getElementById("cart-errors") || document.getElementById("CartDrawer-CartErrors")).textContent = window.cartStrings.error;
                this.disableLoading();
            });
    }
    updateLiveRegions(a, b) {
        if (this.currentItemCount === b) {
            const d = document.getElementById(`Line-item-error-${a}`) || document.getElementById(`CartDrawer-LineItemError-${a}`);
            a = document.getElementById(`Quantity-${a}`) || document.getElementById(`Drawer-quantity-${a}`);
            d.querySelector(".cart-item__error-text").innerHTML = window.cartStrings.quantityError.replace("[quantity]", a.value);
        }
        this.currentItemCount = b;
        this.lineItemStatusElement.setAttribute("aria-hidden", !0);
        const c = document.getElementById("cart-live-region-text") || document.getElementById("CartDrawer-LiveRegionText");
        c.setAttribute("aria-hidden", !1);
        setTimeout(() => {
            c.setAttribute("aria-hidden", !0);
            "undefined" !== typeof window.BOLD &&
                "undefined" !== typeof window.BOLD.common &&
                "undefined" !== typeof window.BOLD.common.eventEmitter &&
                "undefined" !== typeof window.BOLD.common.eventEmitter.emit &&
                BOLD.common.eventEmitter.emit("BOLD_COMMON_cart_loaded");
        }, 1e3);
    }
    getSectionInnerHTML(a, b) {
        return new DOMParser().parseFromString(a, "text/html").querySelector(b).innerHTML;
    }
    enableLoading(a) {
        (document.getElementById("main-cart-items") || document.getElementById("CartDrawer-CartItems")).classList.add("cart__items--disabled");
        const b = this.querySelectorAll(`#CartItem-${a} .loading-overlay`);
        a = this.querySelectorAll(`#CartDrawer-Item-${a} .loading-overlay`);
        [...b, ...a].forEach((c) => c.classList.remove("hidden"));
        document.activeElement.blur();
        this.lineItemStatusElement.setAttribute("aria-hidden", !1);
    }
    disableLoading() {
        (document.getElementById("main-cart-items") || document.getElementById("CartDrawer-CartItems")).classList.remove("cart__items--disabled");
    }
}
customElements.define("cart-items", CartItems);
customElements.get("cart-note") ||
    customElements.define(
        "cart-note",
        class extends HTMLElement {
            constructor() {
                super();
                this.addEventListener(
                    "change",
                    debounce((a) => {
                        a = JSON.stringify({ note: a.target.value });
                        fetch(`${routes.cart_update_url}`, { ...fetchConfig(), body: a });
                    }, 300)
                );
            }
        }
    );
customElements.get("canvas-bag") ||
    customElements.define(
        "canvas-bag",
        class extends HTMLElement {
            constructor() {
                super();
                this.bagVariantId = 39627214684273;
                this.cartItems = document.querySelector("cart-drawer-items");
                this.cartDrawer = document.querySelector("cart-drawer");
                this.addEventListener(
                    "change",
                    debounce((a) => {
                        a = parseFloat(this.querySelector(".quantity__input").value);
                        a = JSON.stringify({ updates: { 39627214684273: a }, sections: this.cartItems.getSectionsToRender().map((b) => b.section), sections_url: window.location.pathname });
                        fetch(`${routes.cart_update_url}`, { ...fetchConfig(), body: a })
                            .then((b) => b.json())
                            .then((b) => {
                                this.cartDrawer.renderContents(b);
                            })
                            .catch((b) => console.log(b));
                    }, 300)
                );
            }
        }
    );
